(34665, 'Matthew 18:29', 'Matthew', 18, 29, 'نو هغه خدمتګار ملګری یې په پښو کې ورته پرېوت او زاري یې ورته وکړه ویې ویل: ‹لږ صبر راته وکړه، پور به دې خلاص کړم.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew18_verse_29.mp3', '', 1761754199, 1761754199),
(34666, 'Matthew 18:30', 'Matthew', 18, 30, 'خو هغه ونه منله او هغه یې په زندان کې واچاوه تر هغې پورې چې د هغه پور ورکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew18_verse_30.mp3', '', 1761754199, 1761754199),
