(34670, 'Matthew 18:34', 'Matthew', 18, 34, 'د هغه بادار دومره په قهر شو چې هغه یې په زندان کې واچاوه او امر یې وکړ چې هغه دې تر هغې پورې وځورول شي، ترڅو یې ټول پور نه وي ورکړی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew18_verse_34.mp3', '', 1761754199, 1761754199),
(34671, 'Matthew 18:35', 'Matthew', 18, 35, 'که چېرې تاسو خپل ورور د زړه نه ونه بخښئ، نو زما اسماني پلار به هم ستاسو سره همداسې وکړي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew18_verse_35.mp3', '', 1761754199, 1761754199),
(34672, 'James 3:1', 'James', 3, 1, 'ای زما خویندو او ورونو! باید هڅه ونه کړئ چې تاسو ټول دې استاذان شئ، ځکه په دې پوهېږئ چې مونږ استاذانو سره به تر نورو زیات حساب کیږي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james3_verse_1.mp3', '', 1761754199, 1761754199),
(34673, 'James 3:2', 'James', 3, 2, 'ځکه چې مونږ ټول ډېرې تېروتنې کوو او څوک چې په خبرو کې تېروتنه نه کوي هغه کامل انسان دی او هغه کولای شي چې خپل ټول بدن په خپل واک کې وساتي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james3_verse_2.mp3', '', 1761754199, 1761754199),
(34674, 'James 3:3', 'James', 3, 3, 'مونږ د اس په خوله کې قیضه اچوو، ترڅو زمونږ تابع شي او هرې خواته چې وغواړو هغه بوځو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james3_verse_3.mp3', '', 1761754199, 1761754199),
