(34694, 'Romans 14:5', 'Romans', 14, 5, 'یو کس یوه ورځ د نورو ورځو نه سپېڅلی ګڼي، په داسې حال کې چې بل کس ټولې ورځې یوشان ګڼي. هرڅوک باید په دې باندې ډاډمن اوسي چې کوم فکر چې هغه یې لري، هغه سم دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans14_verse_5.mp3', '', 1761754199, 1761754199),
(34695, 'Romans 14:6', 'Romans', 14, 6, 'څوک چې یوه ورځ سپېڅلې او مهمه ګڼي، هغه یې څښتن ته د درناوي دپاره ګڼي. څوک چې هرڅه خوري، نو څښتن ته د درناوي دپاره یې خوري، ځکه چې هغه ورباندې د خدای شکر کوي. خو څوک چې هرڅه نه خوري، هغه یې هم څښتن ته د درناوي دپاره نه خوري او د خدای شکر کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans14_verse_6.mp3', '', 1761754199, 1761754199),
(34696, 'Romans 14:7', 'Romans', 14, 7, 'ځکه چې زمونږ څخه هېڅوک هم د خپل ځان دپاره ژوند نه کوي او هېڅوک هم د خپل ځان دپاره نه مړ کیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans14_verse_7.mp3', '', 1761754199, 1761754199),
(34697, 'Romans 14:8', 'Romans', 14, 8, 'ځکه که چېرې مونږ ژوند کوو، نو د څښتن دپاره یې کوو او که مړه کېږو، نو د څښتن دپاره مړه کېږو. نو که چېرې مونږ ژوندي یو یا مړه کېږو، مونږ د څښتن یو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans14_verse_8.mp3', '', 1761754199, 1761754199),
(34698, 'Romans 14:9', 'Romans', 14, 9, 'له همدې امله مسیح مړ شو او بیا راژوندی شو، ترڅو هغه د مړو او ژوندیو دواړو څښتن وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans14_verse_9.mp3', '', 1761754199, 1761754199),
(34699, 'Romans 14:10', 'Romans', 14, 10, 'نو بیا ته ولې د بل ایماندار په هکله قضاوت کوې؟ یا ولې بل ایماندار ته په سپکه سترګه ګورې؟ ځکه چې مونږ ټول به د خدای د قضاوت د تخت په مخکې ودرېږو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans14_verse_10.mp3', '', 1761754199, 1761754199),
(34700, 'Romans 14:11', 'Romans', 14, 11, 'ځکه چې د خدای په کلام کې لیکل شوي دي: څښتن وایي چې زه په خپل ذات باندې قسم خورم چې هر یو به زما په مخکې په ګونډو شي او هر یو به په خپله ژبه اقرار وکړي چې زه خدای یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans14_verse_11.mp3', '', 1761754199, 1761754199),
(34701, 'Romans 14:12', 'Romans', 14, 12, 'نو بیا به مونږ هر یو د خپل ځان په هکله خدای ته حساب ورکوو. د نورو ایماندارانو د ښویېدلو سبب مه کېږئ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans14_verse_12.mp3', '', 1761754199, 1761754199),
(34702, 'Romans 14:13', 'Romans', 14, 13, 'نو راځئ چې نور د یو بل په هکله قضاوت ونه کړو، بلکې د هغې په ځای پرېکړه وکړو چې د بل ایماندار په لاره کې تیږه کېنږدو چې ورباندې وښوییږي او یا د هغه د لارې خنډ شو، ترڅو ګناه وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans14_verse_13.mp3', '', 1761754199, 1761754199),
(34703, 'Romans 14:14', 'Romans', 14, 14, 'زه پوهېږم او څرنګه چې زه په څښتن عیسی باندې ډاډمن یم چې هېڅ شی په خپله ناپاکه نه دی، خو څوک یې چې ناپاک ګڼي، نو د هغه دپاره ناپاکه دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans14_verse_14.mp3', '', 1761754199, 1761754199),
(34704, 'Romans 14:15', 'Romans', 14, 15, 'که چېرې بل ایماندار په هغه خوړو باندې چې ته یې خورې خفه کیږي، نو ته نور په مینه چلند نه کوې. ته چې څه خورې په هغو باندې د هغه چا د تباهۍ او هلاک کېدلو سبب مه ګرځه چې مسیح د هغه دپاره مړ شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans14_verse_15.mp3', '', 1761754199, 1761754199),
(34705, 'Romans 14:16', 'Romans', 14, 16, 'نو څه چې ستاسو دپاره ښه دي، مه پرېږدئ چې نور ورته بد ووایي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans14_verse_16.mp3', '', 1761754199, 1761754199),
(34706, 'Romans 14:17', 'Romans', 14, 17, 'ځکه چې د خدای پاچاهي خوړل او څښل نه دي، بلکې عدالت، سوله او خوشحالي ده چې روح القدس یې ورکوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans14_verse_17.mp3', '', 1761754199, 1761754199),
(34707, 'Romans 14:18', 'Romans', 14, 18, 'څوک چې په دې ډول د مسیح خدمت کوي، نو هغه خدای ته د منلو وړ دی او خلک یې خوښوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans14_verse_18.mp3', '', 1761754199, 1761754199),
(34708, 'Romans 14:19', 'Romans', 14, 19, 'نو بیا راځئ چې د هغو شیانو پسې وګرځو چې زمونږ ترمنځ د سولې او سلامتۍ سبب ګرځي او یو د بل سره مرسته وکړو چې ټینګ ایمان ولرو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans14_verse_19.mp3', '', 1761754199, 1761754199),
(34709, 'Romans 14:20', 'Romans', 14, 20, 'د خوراک په خاطر د خدای کار مه خرابوئ. په حقیقت کې هرڅه پاک دي، خو دا غلطه ده چې کوم څوک هغه څه وخوري چې د نورو د ښویېدلو او ګناه سبب شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans14_verse_20.mp3', '', 1761754199, 1761754199),
(34710, 'Romans 14:21', 'Romans', 14, 21, 'دا به ښه وي چې ته غوښه ونه خورې یا شراب ونه څښې او بل داسې کار ونه کړې چې د نورو ایماندارانو د ښویېدلو سبب شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans14_verse_21.mp3', '', 1761754199, 1761754199);